 * manageQueue(ConcurrentHashMap<collectionId, IndexingInfo>)에 저장되어
 * @Scheduled 폴링(1초)으로 상태를 추적한다.
 */
data class IndexingInfo(
    val collection: Collection,
    val clusterId: String,
    val index: String,
    val scheme: String = "http",
    val host: String = "localhost",
    val port: Int = 8080,
    var indexingJobId: String? = null,
    var status: IndexingStatus = IndexingStatus.RUNNING,
    val startTime: Long = System.currentTimeMillis(),
    var endTime: Long? = null,
    var currentStep: IndexingStep = IndexingStep.FULL_INDEX,
    val nextSteps: ArrayDeque<IndexingStep> = ArrayDeque(),
    var retry: Int = 0,
) {
    val collectionId: String get() = collection.id
}

enum class IndexingStatus {
    RUNNING,
    SUCCESS,
    ERROR,
    STOP,
}

enum class IndexingStep {
    FULL_INDEX,
    DYNAMIC_INDEX,
    EXPOSE,
    REMOVED,
}

