fun resolveTargetIndex(
    client: ElasticsearchClient,
    collection: Collection,
): String {
    val baseId = collection.baseId
    return runCatching {
        val aliases = client.indices().getAlias { it.name(baseId) }
        val currentIndex = aliases.result().keys.firstOrNull()
        when {
            currentIndex == null -> "$baseId-a"
            currentIndex.endsWith("-a") -> "$baseId-b"
            else -> "$baseId-a"
        }
    }.getOrDefault("$baseId-a")
}

private fun swapAlias(
    client: ElasticsearchClient,
    baseId: String,
    newIndex: String,
) {
    val oldIndex =
        runCatching {
            client.indices().getAlias { it.name(baseId) }.result().keys.firstOrNull()
        }.getOrNull()

    client.indices().updateAliases { req ->
        req.actions { action ->
            action.add { it.index(newIndex).alias(baseId) }
            if (oldIndex != null && oldIndex != newIndex) {
                action.remove { it.index(oldIndex).alias(baseId) }
            }
        }
    }
    logger.info("Alias 교체 완료: {} → {} (이전: {})", baseId, newIndex, oldIndex)
}

