package com.cowave.search.collection.service

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.elasticsearch._types.mapping.DynamicMapping
import com.cowave.search.collection.infrastructure.CollectionRepository
import com.cowave.search.collection.model.Collection
import com.cowave.search.collection.model.IndexingInfo
import com.cowave.search.collection.model.IndexingStatus
import com.cowave.search.collection.model.IndexingStep
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.common.exception.NotFoundException
import com.cowave.search.history.model.IndexHistory
import com.cowave.search.history.model.IndexStatus
import com.cowave.search.history.infrastructure.IndexHistoryRepository
import com.cowave.search.history.infrastructure.IndexStatusRepository
import com.cowave.search.notice.TelegramNoticeService
import org.slf4j.LoggerFactory
import org.springframework.beans.factory.annotation.Value
import org.springframework.scheduling.annotation.Async
import org.springframework.scheduling.annotation.Scheduled
import org.springframework.stereotype.Service
import org.springframework.web.client.RestClient
import java.util.concurrent.ConcurrentHashMap

@Service
class CollectionService(
    private val collectionRepository: CollectionRepository,
    private val indexHistoryRepository: IndexHistoryRepository,
    private val indexStatusRepository: IndexStatusRepository,
    private val clientFactory: ElasticsearchClientFactory,
    val indexingScheduler: IndexingScheduler,
    private val telegramNoticeService: TelegramNoticeService,
    private val restClient: RestClient,
    @Value("\${dsearch.timeout:64800000}") private val timeoutMs: Long,
) {
    private val logger = LoggerFactory.getLogger(CollectionService::class.java)

    // 진행 중인 색인 작업 (collectionId → IndexingInfo)
    val manageQueue = ConcurrentHashMap<String, IndexingInfo>()

    // 조회용 큐 (완료/진행 이력)
    val lookupQueue = ConcurrentHashMap<String, IndexingInfo>()

    // manageQueue 제거 예정 목록
    private val deleteQueue = ConcurrentHashMap.newKeySet<String>()

    // ── CRUD ──────────────────────────────────────────────────────────────

    fun findAll(clusterId: String): List<Collection> =
        collectionRepository.findAllByClusterId(clusterId)

    fun findById(
        clusterId: String,
        id: String,
    ): Collection =
        collectionRepository.findByClusterIdAndId(clusterId, id)
            ?: throw NotFoundException("컬렉션을 찾을 수 없습니다: $id")

    fun create(
        clusterId: String,
        collection: Collection,
    ): Collection {
        if (collectionRepository.existsByClusterIdAndBaseId(clusterId, collection.baseId)) {
            throw IllegalArgumentException("이미 존재하는 baseId입니다: ${collection.baseId}")
        }
        return collectionRepository.save(collection.copy(clusterId = clusterId))
    }

    fun delete(
        clusterId: String,
        id: String,
    ) {
        val collection = findById(clusterId, id)
        if (collection.scheduled) {
            indexingScheduler.unregister(clusterId, id)
        }
        collectionRepository.deleteById(id)
    }

    fun updateSource(
        clusterId: String,
        id: String,
        request: Collection,
    ): Collection {
        val collection = findById(clusterId, id)
        val updated =
            collection.copy(
                sourceName = request.sourceName,
                jdbcId = request.jdbcId,
                extIndexer = request.extIndexer,
                esScheme = request.esScheme,
                esHost = request.esHost,
                esPort = request.esPort,
                esUser = request.esUser,
                esPassword = request.esPassword,
                launcherYaml = request.launcherYaml,
                launcherScheme = request.launcherScheme,
                launcherHost = request.launcherHost,
                launcherPort = request.launcherPort,
            )
        return collectionRepository.save(updated)
    }

    fun updateSchedule(
        clusterId: String,
        id: String,
        request: Collection,
    ): Collection {
        val collection = findById(clusterId, id)
        val wasScheduled = collection.scheduled
        val updated =
            collection.copy(
                scheduled = request.scheduled,
                cron = request.cron,
                autoRun = request.autoRun,
            )
        collectionRepository.save(updated)

        // 스케줄 변경 적용
        if (wasScheduled) indexingScheduler.unregister(clusterId, id)
        if (updated.scheduled && updated.cron != null) {
            indexingScheduler.register(clusterId, id, updated.cron!!) {
                startFullIndex(clusterId, id, autoRun = true)
            }
        }
        return updated
    }

    // ── 색인 액션 ──────────────────────────────────────────────────────────

    fun startFullIndex(
        clusterId: String,
        collectionId: String,
        autoRun: Boolean = false,
    ) {
        if (manageQueue.containsKey(collectionId)) {
            logger.warn("컬렉션 {} 이미 색인 중입니다.", collectionId)
            return
        }

        val collection = findById(clusterId, collectionId)
        val client = clientFactory.getClient(clusterId)
        val targetIndex = resolveTargetIndex(client, collection)

        ensureIndexExists(client, targetIndex)
        setRefreshInterval(client, targetIndex, -1)

        val info =
            IndexingInfo(
                collection = collection,
                clusterId = clusterId,
                index = targetIndex,
            ).also { it.nextSteps.add(IndexingStep.EXPOSE) }

        if (collection.extIndexer) {
            startExternalIndexer(info)
        } else {
            info.status = IndexingStatus.SUCCESS
            info.currentStep = IndexingStep.EXPOSE
        }

        manageQueue[collectionId] = info
        lookupQueue[collectionId] = info

        indexStatusRepository.save(
            IndexStatus(
                clusterId = clusterId,
                collectionId = collectionId,
                index = targetIndex,
                startTime = info.startTime,
                status = "READY",
            ),
        )
    }

    fun stopIndexing(
        clusterId: String,
        collectionId: String,
    ) {
        val info = manageQueue[collectionId] ?: return
        if (info.collection.extIndexer && info.indexingJobId != null) {
            stopExternalIndexer(info)
        }
        info.status = IndexingStatus.STOP
        deleteQueue.add(collectionId)
    }

    fun expose(
        clusterId: String,
        collectionId: String,
    ) {
        val collection = findById(clusterId, collectionId)
        val client = clientFactory.getClient(clusterId)
        val targetIndex = resolveTargetIndex(client, collection)
        swapAlias(client, collection.baseId, targetIndex)
    }

    // ── 1초 폴링 ──────────────────────────────────────────────────────────

    @Scheduled(fixedDelay = 1000)
    fun pollManageQueue() {
        deleteQueue.forEach { id ->
            manageQueue.remove(id)
            deleteQueue.remove(id)
        }

        manageQueue.values.toList().forEach { info ->
            runCatching { processIndexingInfo(info) }.onFailure { e ->
                logger.error("색인 폴링 오류 [{}]: {}", info.collectionId, e.message)
            }
        }
    }

    private fun processIndexingInfo(info: IndexingInfo) {
        // 타임아웃 체크
        if (System.currentTimeMillis() - info.startTime > timeoutMs) {
            logger.warn("색인 타임아웃: {}", info.collectionId)
            info.status = IndexingStatus.ERROR
            finalizeIndexing(info, "TIMEOUT")
            return
        }

        when (info.status) {
            IndexingStatus.RUNNING -> {
                if (info.collection.extIndexer) checkExternalIndexerStatus(info)
            }
            IndexingStatus.SUCCESS -> {
                val nextStep = info.nextSteps.removeFirstOrNull()
                if (nextStep == IndexingStep.EXPOSE) {
                    runCatching {
                        val client = clientFactory.getClient(info.clusterId)
                        swapAlias(client, info.collection.baseId, info.index)
                        restoreRefreshInterval(client, info.index, info.collection.refreshInterval)
                        Thread.sleep(60_000)
                    }.onFailure { e ->
                        logger.error("Alias 교체 실패 [{}]: {}", info.collectionId, e.message)
                    }
                }
                finalizeIndexing(info, "SUCCESS")
            }
            IndexingStatus.ERROR, IndexingStatus.STOP -> {
                val resultStatus = info.status.name
                telegramNoticeService.sendMessage("색인 $resultStatus: ${info.collection.name} (${info.collectionId})")
                finalizeIndexing(info, resultStatus)
            }
        }
    }

    private fun finalizeIndexing(
        info: IndexingInfo,
        status: String,
    ) {
        info.endTime = System.currentTimeMillis()
        indexHistoryRepository.save(
            IndexHistory(
                clusterId = info.clusterId,
                collectionId = info.collectionId,
                index = info.index,
                jobType = info.currentStep.name,
                startTime = info.startTime,
                endTime = info.endTime,
                autoRun = false,
                status = status,
            ),
        )
        deleteQueue.add(info.collectionId)
    }

    // ── A/B 스왑 로직 ─────────────────────────────────────────────────────

    /**
     * 현재 Alias가 가리키는 인덱스의 반대편을 색인 타겟으로 결정.
     * Alias 없으면 {baseId}-a가 기본값.
     */
    fun resolveTargetIndex(
        client: ElasticsearchClient,
        collection: Collection,
    ): String {
        val baseId = collection.baseId
        return runCatching {
            // getAlias 응답: Map<indexName, IndexAliases>
            val aliasMap = client.indices().getAlias { it.name(baseId) }
            val currentIndex = aliasMap.keys().firstOrNull()
            when {
                currentIndex == null -> "$baseId-a"
                currentIndex.endsWith("-a") -> "$baseId-b"
                else -> "$baseId-a"
            }
        }.getOrDefault("$baseId-a")
    }

    private fun swapAlias(
        client: ElasticsearchClient,
        baseId: String,
        newIndex: String,
    ) {
        val oldIndex =
            runCatching {
                client.indices().getAlias { it.name(baseId) }.keys().firstOrNull()
            }.getOrNull()

        client.indices().updateAliases { req ->
            if (oldIndex != null && oldIndex != newIndex) {
                req.actions { a -> a.remove { it.index(oldIndex).alias(baseId) } }
            }
            req.actions { a -> a.add { it.index(newIndex).alias(baseId) } }
        }
        logger.info("Alias 교체 완료: {} → {} (이전: {})", baseId, newIndex, oldIndex)
    }

    private fun ensureIndexExists(
        client: ElasticsearchClient,
        indexName: String,
    ) {
        val exists = client.indices().exists { it.index(indexName) }.value()
        if (!exists) {
            client.indices().create { it.index(indexName) }
            logger.info("인덱스 생성: {}", indexName)
        }
    }

    private fun setRefreshInterval(
        client: ElasticsearchClient,
        indexName: String,
        seconds: Int,
    ) {
        runCatching {
            client.indices().putSettings { req ->
                req.index(indexName).settings { s ->
                    s.refreshInterval { t -> t.time("${seconds}s") }
                }
            }
        }.onFailure { e ->
            logger.warn("refresh_interval 설정 실패 [{}]: {}", indexName, e.message)
        }
    }

    private fun restoreRefreshInterval(
        client: ElasticsearchClient,
        indexName: String,
        seconds: Int?,
    ) {
        val value = if (seconds != null && seconds > 0) "${seconds}s" else "1s"
        runCatching {
            client.indices().putSettings { req ->
                req.index(indexName).settings { s ->
                    s.refreshInterval { t -> t.time(value) }
                }
            }
        }.onFailure { e ->
            logger.warn("refresh_interval 복원 실패 [{}]: {}", indexName, e.message)
        }
    }

    // ── 외부 인덱서 연동 ──────────────────────────────────────────────────

    @Async
    fun startExternalIndexer(info: IndexingInfo) {
        runCatching {
            val url = "${info.scheme}://${info.host}:${info.port}/async/start"
            val response =
                restClient
                    .post()
                    .uri(url)
                    .retrieve()
                    .body(MutableMap::class.java)
            info.indexingJobId = response?.get("id")?.toString()
            logger.info("외부 인덱서 시작 [{}]: jobId={}", info.collectionId, info.indexingJobId)
        }.onFailure { e ->
            logger.error("외부 인덱서 시작 실패 [{}]: {}", info.collectionId, e.message)
            info.status = IndexingStatus.ERROR
        }
    }

    private fun checkExternalIndexerStatus(info: IndexingInfo) {
        val jobId = info.indexingJobId ?: return
        runCatching {
            val url = "${info.scheme}://${info.host}:${info.port}/async/status?id=$jobId"
            val response =
                restClient
                    .get()
                    .uri(url)
                    .retrieve()
                    .body(MutableMap::class.java)
            when (response?.get("status")?.toString()) {
                "SUCCESS" -> info.status = IndexingStatus.SUCCESS
                "ERROR" -> info.status = IndexingStatus.ERROR
                "STOP" -> info.status = IndexingStatus.STOP
                else -> {} // RUNNING — 계속 대기
            }
        }.onFailure { e ->
            logger.warn("외부 인덱서 상태 조회 실패 [{}]: {}", info.collectionId, e.message)
            if (++info.retry >= 50) info.status = IndexingStatus.ERROR
        }
    }

    private fun stopExternalIndexer(info: IndexingInfo) {
        val jobId = info.indexingJobId ?: return
        runCatching {
            val url = "${info.scheme}://${info.host}:${info.port}/async/stop?id=$jobId"
            restClient.put().uri(url).retrieve().toBodilessEntity()
        }.onFailure { e ->
            logger.warn("외부 인덱서 중지 실패 [{}]: {}", info.collectionId, e.message)
        }
    }

    fun getCurrentJob(
        clusterId: String,
        collectionId: String,
    ): IndexingInfo? = lookupQueue[collectionId]
}

package com.cowave.search.collection.service

import co.elastic.clients.elasticsearch.ElasticsearchClient
